'use strict';

// Every auto-generated playlist rows is born here.
//
// The Playlists-page "Show auto-generated" toggle filters on is_auto_generated, and the
// content-only schedule path hand-wrote its own INSERT without the flag — so its
// `Scheduled:` playlists could never be hidden. The flag is owned by construction now:
// callers describe the playlist, this module stamps is_auto_generated=1, and there is
// no other INSERT path for generated rows (user-created playlists go through
// routes/playlists.js, which leaves the flag at its 0 default).

const { v4: uuidv4 } = require('uuid');
const { resolveItemDuration } = require('./item-duration');

// Defaults mirror the table (status NOT NULL DEFAULT 'draft', description DEFAULT '') so a
// call site that omits them writes exactly what its old hand-written INSERT wrote.
function createAutoGeneratedPlaylist(db, {
  name, workspaceId = null, userId, status = 'draft', description = '',
  publishedSnapshot = null, publishedStructure = null,
}) {
  const id = uuidv4();
  db.prepare(`INSERT INTO playlists (id, user_id, workspace_id, name, description, status,
                                     is_auto_generated, published_snapshot, published_structure)
              VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?)`)
    .run(id, userId, workspaceId, name, description, status, publishedSnapshot, publishedStructure);
  return id;
}

// A playlist that backs a content-carrying schedule is the throwaway the schedule POST
// handler invents, whatever its flag or name says. Structural selector, never the display
// name: names are user-editable (a hand-made playlist can share the `Scheduled:` prefix,
// and a generated one can be renamed), while schedules carries both ids.
//
// Used in two places: the one-shot boot backfill (db/database.js via runOnce) for rows
// that pre-date the flag, and after a workspace import (routes/status.js) — a backup
// written before the flag existed restores with is_auto_generated=0, and the one-shot
// has already run, so without this the restored throwaways would never be flagged.
function backfillScheduledPlaylists(db) {
  return db.prepare(`
    UPDATE playlists SET is_auto_generated = 1
    WHERE is_auto_generated = 0
      AND id IN (SELECT playlist_id FROM schedules WHERE content_id IS NOT NULL AND playlist_id IS NOT NULL)
  `).run().changes;
}

// A schedule's throwaway must not outlive the schedule — but only when it is still an
// untouched throwaway: auto-generated, holding exactly the one scheduled item (more
// means a human adopted it via the Playlists page), and referenced by nothing else
// (a second schedule, a device/group/wall/deck pointer, nesting, or an API token).
// Callers: schedule DELETE, and schedule PUT when the playlist pointer moves away.
// Returns true when a row was actually removed.
function deleteAutoGeneratedPlaylistIfOrphan(db, playlistId) {
  if (!playlistId) return false;
  const pl = db.prepare('SELECT is_auto_generated FROM playlists WHERE id = ?').get(playlistId);
  if (!pl || !pl.is_auto_generated) return false;
  if (db.prepare('SELECT COUNT(*) n FROM playlist_items WHERE playlist_id = ?').get(playlistId).n !== 1) return false;
  const refs = [
    ['schedules', 'playlist_id'],
    ['devices', 'playlist_id'],
    ['devices', 'scheduled_playlist_id'],
    ['device_groups', 'playlist_id'],
    ['video_walls', 'playlist_id'],
    ['slide_decks', 'playlist_id'],
    ['playlist_items', 'child_playlist_id'],
    ['api_token_targets', 'playlist_id'],
    ['agency_notifications', 'playlist_id'],
  ];
  for (const [table, col] of refs) {
    try {
      if (db.prepare(`SELECT 1 FROM ${table} WHERE ${col} = ? LIMIT 1`).get(playlistId)) return false;
    } catch { /* table/column pre-dates this DB: treat as no reference */ }
  }
  db.prepare('DELETE FROM playlist_items WHERE playlist_id = ?').run(playlistId);
  db.prepare('DELETE FROM playlists WHERE id = ?').run(playlistId);
  return true;
}

// PUT content change on a schedule that owns a throwaway: the playlist still holds the
// OLD item, so the screen keeps playing the old file while the calendar shows the new
// one. Rewrite the single item to the new content. Returns true when it rewrote (the
// caller republishes the snapshot); false when the playlist is not an untouched
// throwaway — an explicit override wins (content_id is vestigial there) and an adopted
// multi-item playlist belongs to its human, so both are left alone.
function rewriteScheduledPlaylistItem(db, playlistId, contentId) {
  if (!playlistId || !contentId) return false;
  const pl = db.prepare('SELECT is_auto_generated FROM playlists WHERE id = ?').get(playlistId);
  if (!pl || !pl.is_auto_generated) return false;
  if (db.prepare('SELECT COUNT(*) n FROM playlist_items WHERE playlist_id = ?').get(playlistId).n !== 1) return false;
  const c = db.prepare('SELECT filename, duration_sec FROM content WHERE id = ?').get(contentId);
  if (!c) return false;
  db.prepare('DELETE FROM playlist_items WHERE playlist_id = ?').run(playlistId);
  db.prepare('INSERT INTO playlist_items (playlist_id, content_id, sort_order, duration_sec) VALUES (?, ?, 0, ?)')
    .run(playlistId, contentId, resolveItemDuration(null, c));
  return true;
}

module.exports = {
  createAutoGeneratedPlaylist,
  backfillScheduledPlaylists,
  deleteAutoGeneratedPlaylistIfOrphan,
  rewriteScheduledPlaylistItem,
};
